import streamlit as st
import streamlit.components.v1 as components

st.set_page_config(page_title='Grocery AI', page_icon='🥬', layout='centered')
st.markdown('''<style>header[data-testid="stHeader"]{background:#0b1220} .stApp{background:#0b1220;color:#fff} .block-container{padding-top:1.3rem;max-width:750px} #MainMenu,footer{visibility:hidden}</style>''', unsafe_allow_html=True)

html = r'''
<div id="grocery" style="font-family:system-ui,sans-serif;color:white;background:#0b1220;padding:20px;border-radius:20px;box-sizing:border-box;min-height:720px">
<style>
#grocery *{box-sizing:border-box}#grocery .top{display:flex;justify-content:space-between;align-items:center}#grocery .muted{color:#91a2b6;font-size:12px}#grocery .pill{background:#193f35;color:#7df0b8;border-radius:40px;padding:8px 12px;font-size:11px}#grocery .center{text-align:center}#grocery .orbit{width:230px;height:230px;border-radius:50%;position:relative;display:grid;place-items:center;background:radial-gradient(circle,#21443b,#111e2b 65%,transparent 72%);border:1px solid #315d51;margin:23px auto}#grocery .ring{position:absolute;inset:12px;border-radius:50%;border:3px dashed #5de7b1;animation:spin 9s linear infinite;box-shadow:0 0 24px #49e3a744}#grocery .ring2{position:absolute;inset:32px;border-radius:50%;border:2px solid #64e9ad77;animation:pulse 2s ease-in-out infinite}#grocery .scan{position:absolute;left:25px;right:25px;height:2px;background:#71ffd0;box-shadow:0 0 15px #71ffd0;animation:scan 2.5s ease-in-out infinite}#grocery .emoji{font-size:76px;filter:drop-shadow(0 8px 15px #0008);animation:bob 3s ease-in-out infinite}#grocery .bars{display:flex;align-items:center;justify-content:center;gap:4px;height:35px}#grocery .bars span{width:4px;background:#61eab3;border-radius:4px;animation:wave 1s ease-in-out infinite alternate}#grocery .choices{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:24px}#grocery button{border:0;cursor:pointer;color:white;border-radius:12px;padding:13px 6px;background:#1b2939;font-size:14px}#grocery button.active{background:#214f42;outline:1px solid #68e8b1}#grocery #start{width:100%;background:#72edb5;color:#081a16;font-weight:700;margin-top:15px;padding:16px}#grocery .result{background:#162435;border:1px solid #293c4b;border-radius:16px;margin-top:20px;padding:18px}#grocery .line{display:flex;justify-content:space-between;align-items:center;gap:12px}#grocery .track{height:8px;border-radius:10px;background:#334155;overflow:hidden;margin-top:20px}#grocery .fill{height:100%;width:0;background:#65e8ae;transition:width 1.5s ease}#grocery .big{font-size:22px;font-weight:750}#grocery .small{font-size:12px;color:#91a2b6} @keyframes spin{to{transform:rotate(360deg)}}@keyframes pulse{50%{transform:scale(1.12);opacity:.25}}@keyframes scan{0%,100%{top:24%;opacity:.1}50%{top:76%;opacity:1}}@keyframes bob{50%{transform:translateY(-9px)}}@keyframes wave{from{height:5px}to{height:28px}}@media(prefers-reduced-motion:reduce){#grocery *{animation:none!important}}
</style>
<div class="top"><div><div style="font-size:24px;font-weight:800">◉ grocery<span style="color:#68e8b1">.ai</span></div><div class="muted">Visual grocery intelligence</div></div><div class="pill">● DEMO LIVE</div></div>
<div class="center" style="margin-top:25px"><div class="muted" style="letter-spacing:2px">RECOGNITION ENGINE</div><div id="status" style="font-size:21px;font-weight:650;margin-top:8px">Ready to identify</div></div>
<div class="orbit"><div class="ring"></div><div class="ring2"></div><div class="scan"></div><div id="emoji" class="emoji">🍎</div></div>
<div id="bars" class="bars"></div><div class="center muted" id="sub">Animated visual recognition</div>
<div class="choices"><button class="active" data-i="0">🍎 Apple</button><button data-i="1">🥛 Milk</button><button data-i="2">🍌 Banana</button></div>
<button id="start">◎ Identify grocery</button>
<div class="result"><div class="line"><span class="small" style="letter-spacing:1px">RECOGNITION RESULT</span><span id="confidence" style="font-size:12px;color:#7be9b5">Awaiting scan</span></div><div class="line" style="margin-top:20px"><div><div id="name" class="big">Red Apple</div><div id="category" class="small" style="margin-top:4px">Fresh produce</div></div><div id="price" class="big">₹180/kg</div></div><div class="track"><div id="progress" class="fill"></div></div><div class="line" style="margin-top:12px"><span id="detail" class="small">Select and scan an item</span><span class="small">Illustrative data</span></div></div>
<div class="center muted" style="margin-top:18px">Prototype · Simulated AI recognition · Sample prices</div>
</div>
<script>
(()=>{const root=document.getElementById('grocery'),el=id=>root.querySelector('#'+id),items=[{emoji:'🍎',name:'Red Apple',cat:'Fresh produce',price:'₹180/kg',detail:'Fruit · Produce',confidence:97},{emoji:'🥛',name:'Fresh Milk',cat:'Dairy & chilled',price:'₹64/L',detail:'Dairy · Refrigerated',confidence:95},{emoji:'🍌',name:'Banana',cat:'Fresh produce',price:'₹60/dozen',detail:'Fruit · Produce',confidence:98}];let selected=0,busy=false;for(let i=0;i<16;i++){let b=document.createElement('span');b.style.animationDelay=i*.09+'s';el('bars').appendChild(b)}root.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>{if(busy)return;selected=+b.dataset.i;el('emoji').textContent=items[selected].emoji;el('status').textContent='Ready to identify';el('confidence').textContent='Awaiting scan';el('progress').style.width='0%';root.querySelectorAll('[data-i]').forEach(c=>c.classList.remove('active'));b.classList.add('active')});el('start').onclick=()=>{if(busy)return;busy=true;let x=items[selected];el('status').textContent='Analyzing grocery…';el('sub').textContent='Extracting visual features';el('progress').style.width='30%';el('start').textContent='Recognizing…';setTimeout(()=>{el('progress').style.width='75%';el('sub').textContent='Matching product category'},700);setTimeout(()=>{el('progress').style.width=x.confidence+'%';el('status').textContent='✓ Grocery identified';el('name').textContent=x.name;el('category').textContent=x.cat;el('price').textContent=x.price;el('detail').textContent=x.detail;el('confidence').textContent=x.confidence+'% simulated confidence';el('sub').textContent='Recognition complete';el('start').textContent='↻ Scan again';busy=false},1700)}})();
</script>
'''
components.html(html, height=790, scrolling=False)
